 String email(UUID a){return "departure-"+a+"@example.test";}
 void grant(UUID a,String cap,UUID space){if(space!=null&&db.queryForObject("SELECT count(*) FROM workspaces WHERE id=?",Integer.class,space)==0)return;db.update("INSERT INTO governance_capabilities(tenant_id,account_id,workspace_id,capability,granted_by) VALUES (?,?,?,?,?)",tenant,a,space,cap,admin);}
 DepartureService.View offboard(){return service.beginOffboard(admin,tenant,member,UUID.randomUUID(),0,"已明确确认离职，按固定隔离期清理",true);}
 DepartureService.View exit(){grant(reader,"BULK_EXPORT",shared);return service.beginExit(admin,tenant,UUID.randomUUID(),0,"合成企业确认退出",List.of(new DepartureService.ExportGrant(reader,shared)),true);}
 UUID upload(UUID space,String name){return materials.upload(member,tenant,space,null,null,null,UUID.randomUUID(),new MockMultipartFile("file",name,"text/plain",("合成内容 "+name).getBytes())).id();}
 void drain(){for(int i=0;i<100;i++){var job=cleanup.claim();if(job==null)break;for(UUID object:cleanup.pending(job)){cleanup.remove(object);cleanup.removed(job,object);}cleanup.finish(job);}for(UUID id:objectCleanup.pending())objectCleanup.clean(id);}
 void generateArchives(){for(int i=0;i<200;i++){archiveWorker.runOnce();if(db.queryForObject("SELECT count(*) FROM departure_export_parts WHERE state='QUEUED'",Integer.class)==0)break;}}
 @Test void exportDesignationUsesRecipientRightsWithinCallersReadableScopes(){grant(reader,"BULK_EXPORT",shared);assertEquals(List.of(shared),service.exportScopes(admin,tenant,reader,0,20).stream().map(DepartureService.ExportScope::workspaceId).toList());assertTrue(service.exportScopes(admin,tenant,successor,0,20).isEmpty());db.update("DELETE FROM workspace_members WHERE tenant_id=? AND workspace_id=? AND account_id=?",tenant,shared,admin);assertTrue(service.exportScopes(admin,tenant,reader,0,20).isEmpty());assertThrows(IdentityException.class,()->service.exportScopes(reader,tenant,admin,0,20));}
 @Test void offboardRequiresExplicitCapabilityAndNeverTransfersPrivateOwnership(){assertEquals(403,assertThrows(IdentityException.class,()->service.beginOffboard(successor,tenant,member,UUID.randomUUID(),0,"无权",true)).status);var result=offboard();assertEquals("ISOLATING",result.execution().state());assertEquals("DISABLED",db.queryForObject("SELECT status FROM tenant_memberships WHERE tenant_id=? AND account_id=?",String.class,tenant,member));assertEquals(0,db.queryForObject("SELECT count(*) FROM workspace_members WHERE tenant_id=? AND account_id=?",Integer.class,tenant,member));assertEquals(member,db.queryForObject("SELECT owner_id FROM workspaces WHERE id=?",UUID.class,personal));assertThrows(IdentityException.class,()->gate.requireActiveBusiness(member,tenant));assertFalse(gate.allowsTask(task));assertThrows(IdentityException.class,()->gate.requireMemberActivation(tenant,member));assertThrows(Exception.class,()->db.update("UPDATE tenant_memberships SET status='ACTIVE' WHERE tenant_id=? AND account_id=?",tenant,member));}
 @Test void confirmedSpaceResponsibilitiesCannotBypassExplicitOldAccessChoiceThroughLegacyHandover(){db.update("UPDATE workspaces SET responsibility_confirmed=true WHERE id=?",shared);var error=assertThrows(IdentityException.class,()->service.handover(admin,tenant,UUID.randomUUID(),"WORKSPACE_OWNER",shared,shared,member,successor,0));assertEquals("SPACE_OWNER_USE_MANAGEMENT",error.code);assertEquals(member,db.queryForObject("SELECT owner_id FROM workspaces WHERE id=?",UUID.class,shared));}
 @Test void sharedHandoverUsesExistingMaintainerAndPreservesPrivateAssets(){assertThrows(IdentityException.class,()->service.handover(admin,tenant,UUID.randomUUID(),"WORKSPACE_OWNER",personal,personal,member,successor,0));assertThrows(IdentityException.class,()->service.handover(admin,tenant,UUID.randomUUID(),"WORKSPACE_OWNER",shared,shared,member,reader,0));UUID key=UUID.randomUUID();var receipt=service.handover(admin,tenant,key,"WORKSPACE_OWNER",shared,shared,member,successor,0);assertEquals(receipt,service.handover(admin,tenant,key,"WORKSPACE_OWNER",shared,shared,member,successor,0));assertEquals(successor,db.queryForObject("SELECT owner_id FROM workspaces WHERE id=?",UUID.class,shared));assertEquals(member,db.queryForObject("SELECT owner_id FROM conversations WHERE id=?",UUID.class,conversation));assertEquals(member,db.queryForObject("SELECT owner_id FROM workspaces WHERE id=?",UUID.class,personal));}
 @Test void offboardStopsTaskUsingActualAttemptFlowAndIsolatesOnlyPrivateMaterials(){UUID privateMaterial=upload(personal,"私人资料.txt"),sharedMaterial=upload(shared,"企业资产.txt");var e=offboard();processor.process(e.execution().id());assertEquals("INTERRUPTED",db.queryForObject("SELECT status FROM conversation_tasks WHERE id=?",String.class,task));assertEquals("ISOLATED",service.get(admin,tenant,e.execution().id()).execution().state());assertEquals(0,db.queryForObject("SELECT count(*) FROM active_materials WHERE id=?",Integer.class,privateMaterial));assertEquals(1,db.queryForObject("SELECT count(*) FROM active_materials WHERE id=?",Integer.class,sharedMaterial));assertEquals(1,db.queryForObject("SELECT count(*) FROM departure_materials WHERE execution_id=?",Integer.class,e.execution().id()));assertEquals("PENDING_VERIFICATION",service.get(admin,tenant,e.execution().id()).backupState());}
 @Test void cancelRestoresOnlyStillValidIdentityAndNoOldGrantsOrAutomaticTaskRestart(){UUID file=upload(personal,"可恢复私人资料.txt");var e=offboard();processor.process(e.execution().id());var current=service.get(admin,tenant,e.execution().id());service.command(admin,tenant,e.execution().id(),UUID.randomUUID(),current.execution().revision(),"CANCEL_OFFBOARD");assertThrows(IdentityException.class,()->gate.requireActiveBusiness(member,tenant));processor.process(e.execution().id());var restored=service.get(admin,tenant,e.execution().id());assertEquals("CANCELLED",restored.execution().state());assertEquals("ACTIVE",db.queryForObject("SELECT status FROM tenant_memberships WHERE tenant_id=? AND account_id=?",String.class,tenant,member));assertEquals(0,db.queryForObject("SELECT count(*) FROM workspace_members WHERE tenant_id=? AND account_id=?",Integer.class,tenant,member));assertEquals("INTERRUPTED",db.queryForObject("SELECT status FROM conversation_tasks WHERE id=?",String.class,task));assertEquals(1,db.queryForObject("SELECT count(*) FROM active_materials WHERE id=?",Integer.class,file));gate.requirePrivateRead(member,tenant);}
 @Test void exitWindowAllowsOnlyDesignatedCurrentSharedExportAndNoPrivateOrNewBusiness(){var e=exit();assertEquals("EXPORT_WINDOW",e.execution().state());gate.requireContentRead(reader,tenant,shared);assertThrows(IdentityException.class,()->gate.requireContentRead(admin,tenant,shared));assertThrows(IdentityException.class,()->gate.requireContentRead(reader,tenant,personal));assertThrows(IdentityException.class,()->gate.requirePrivateRead(reader,tenant));assertThrows(IdentityException.class,()->gate.requireActiveBusiness(reader,tenant));assertThrows(IdentityException.class,()->gate.requireTenantActivation(tenant));assertEquals(e.execution().deadline(),gate.capPackageExpiry(reader,tenant,shared,e.execution().deadline().plusSeconds(10)));db.update("DELETE FROM governance_capabilities WHERE tenant_id=? AND account_id=? AND capability='BULK_EXPORT'",tenant,reader);assertThrows(IdentityException.class,()->gate.requireContentRead(reader,tenant,shared));}
 @Test void deadlineClosesReadsBeforeWorkerAndActualCleanupDoesNotAddThirtyMoreDays(){UUID file=upload(shared,"原件实际清理.txt");var e=exit();Instant due=e.execution().deadline();assertEquals(Duration.ofDays(30),Duration.between(e.execution().effectiveAt(),due));db.update("UPDATE departure_executions SET deadline=clock_timestamp()-interval '1 second',effective_at=clock_timestamp()-interval '31 days' WHERE id=?",e.execution().id());assertThrows(IdentityException.class,()->gate.requireContentRead(reader,tenant,shared));start=due.plusSeconds(1);processor.process(e.execution().id());assertEquals("CLEANING",service.get(admin,tenant,e.execution().id()).execution().state());assertNotEquals("COMPLETE",service.get(admin,tenant,e.execution().id()).execution().state());for(int i=0;i<20;i++){drain();processor.process(e.execution().id());if(service.get(admin,tenant,e.execution().id()).execution().state().equals("COMPLETE"))break;}var complete=service.get(admin,tenant,e.execution().id());assertEquals("COMPLETE",complete.execution().state());assertNotNull(complete.execution().completedAt());assertEquals("PENDING_VERIFICATION",complete.backupState());assertEquals("PURGED",db.queryForObject("SELECT state FROM content_lifecycle WHERE object_id=? AND object_kind='MATERIAL'",String.class,file));assertEquals("内容已按对象生命周期清理",db.queryForObject("SELECT prompt FROM conversation_tasks WHERE id=?",String.class,task));assertThrows(IdentityException.class,()->gate.requireActiveBusiness(admin,tenant));}
 @Test void lostReplyReplayDoesNotResetDeadlineAndConflictingPayloadFails(){UUID key=UUID.randomUUID();var one=service.beginOffboard(admin,tenant,member,key,0,"同一次明确离职",true);start=start.plus(Duration.ofDays(2));var again=service.beginOffboard(admin,tenant,member,key,0,"同一次明确离职",true);assertEquals(one.execution().id(),again.execution().id());assertEquals(one.execution().deadline(),again.execution().deadline());assertEquals(1,db.queryForObject("SELECT count(*) FROM departure_executions WHERE tenant_id=?",Integer.class,tenant));assertEquals("IDEMPOTENCY_CONFLICT",assertThrows(IdentityException.class,()->service.beginOffboard(admin,tenant,member,key,0,"改成另一次说明",true)).code);}
 @Test void realExitZipContainsExactOriginalAndIndependentExperienceWithoutPrivateBodies()throws Exception{UUID original=upload(shared,"共享原件.txt");upload(personal,"私人绝不迁出.txt");grant(member,"EXPERIENCE_MAINTAIN",shared);var body=new com.dreamcore.workspace.experience.ExperienceService.Content("METHOD","独立方法","独立摘要","明确输入的独立正文",List.of("退出"),"适合此类工作","不适用于个人","无","人工整理","INDEPENDENT_COPY");var experience=experiences.create(member,tenant,shared,UUID.randomUUID(),body,List.of());experiences.publish(member,tenant,shared,experience.id(),UUID.randomUUID(),experience.revision(),experience.version().id(),true);var e=exit();UUID key=UUID.randomUUID();var inventory=archives.create(reader,tenant,e.execution().id(),shared,key,false);assertEquals(2,inventory.itemCount());assertFalse(inventory.fullTenantMigration());assertEquals(inventory.id(),archives.create(reader,tenant,e.execution().id(),shared,key,false).id());var part=archives.next(reader,tenant,inventory.id(),UUID.randomUUID());generateArchives();var done=archives.part(reader,tenant,part.id());assertEquals("READY",done.state());assertTrue(done.canDownload());assertEquals(2,done.items().size());var out=new java.io.ByteArrayOutputStream();archives.download(reader,tenant,part.id(),info->assertTrue(info.bytes()>0),out);var entries=new HashMap<String,byte[]>();try(var zip=new java.util.zip.ZipInputStream(new java.io.ByteArrayInputStream(out.toByteArray()))){for(var entry=zip.getNextEntry();entry!=null;entry=zip.getNextEntry())entries.put(entry.getName(),zip.readAllBytes());}assertEquals(3,entries.size());assertTrue(entries.keySet().stream().anyMatch(n->n.endsWith("共享原件.txt")));assertEquals("合成内容 共享原件.txt",new String(entries.entrySet().stream().filter(x->x.getKey().endsWith("共享原件.txt")).findFirst().orElseThrow().getValue(),java.nio.charset.StandardCharsets.UTF_8));String experienceJson=new String(entries.entrySet().stream().filter(x->x.getKey().contains("experience-")).findFirst().orElseThrow().getValue(),java.nio.charset.StandardCharsets.UTF_8);assertTrue(experienceJson.contains("明确输入的独立正文"));assertTrue(experienceJson.contains("NOT_EVALUATED"));assertFalse(experienceJson.contains("私人原始问题"));assertFalse(experienceJson.contains("referenceId"));assertFalse(json.readTree(entries.get("_exit-manifest.json")).get("fullTenantMigration").asBoolean());assertTrue(archives.get(reader,tenant,inventory.id()).selectedScopeComplete());db.queryForList("SELECT scrub_departure_material_version(?)",db.queryForObject("SELECT id FROM material_versions WHERE material_id=?",UUID.class,original));assertEquals(0,db.queryForObject("SELECT count(*) FROM departure_archive_chunks WHERE part_id=?",Integer.class,part.id()));assertEquals("COMPLETE",archives.receipt(reader,tenant,part.id()).cleanupState());assertThrows(IdentityException.class,()->archives.download(reader,tenant,part.id(),info->{},new java.io.ByteArrayOutputStream()));}
 @Test void exitPartRevocationAndExpiryCannotReuseOldZip()throws Exception{upload(shared,"退出授权.txt");var e=exit();var inventory=archives.create(reader,tenant,e.execution().id(),shared,UUID.randomUUID(),false);UUID key=UUID.randomUUID();var p=archives.next(reader,tenant,inventory.id(),key);assertEquals(p.id(),archives.next(reader,tenant,inventory.id(),key).id());generateArchives();var ready=archives.part(reader,tenant,p.id());assertTrue(ready.canDownload());assertTrue(ready.expiresAt().isBefore(e.execution().deadline()));db.update("DELETE FROM governance_capabilities WHERE tenant_id=? AND account_id=? AND capability='BULK_EXPORT'",tenant,reader);assertThrows(IdentityException.class,()->archives.download(reader,tenant,p.id(),info->{},new java.io.ByteArrayOutputStream()));grant(reader,"BULK_EXPORT",shared);db.update("UPDATE departure_export_parts SET expires_at=clock_timestamp()-interval '1 second' WHERE id=?",p.id());start=start.plus(Duration.ofDays(8));assertFalse(archives.part(reader,tenant,p.id()).canDownload());generateArchives();var receipt=archives.receipt(reader,tenant,p.id());assertEquals("EXPIRED",receipt.state());assertEquals(1,archives.receipts(reader,tenant,e.execution().id(),0,20).items().size());assertEquals("COMPLETE",receipt.cleanupState());assertTrue(receipt.removedBytes()>0);assertEquals(0,db.queryForObject("SELECT count(*) FROM departure_archive_chunks WHERE part_id=?",Integer.class,p.id()));}
 @Test void missingItemsProducePartialReceiptAndEmptyInventoryCannotFakeSuccess(){UUID missing=upload(shared,"将被删除.txt");upload(shared,"保留.txt");var e=exit();var inventory=archives.create(reader,tenant,e.execution().id(),shared,UUID.randomUUID(),false);db.update("INSERT INTO content_lifecycle(tenant_id,workspace_id,object_kind,object_id,state,changed_by,changed_at,trashed_at,purge_after) VALUES (?,?,'MATERIAL',?,'TRASHED',?,now(),now(),now()+interval '30 days')",tenant,shared,missing,admin);var p=archives.next(reader,tenant,inventory.id(),UUID.randomUUID());generateArchives();var done=archives.part(reader,tenant,p.id());assertEquals("PARTIAL",done.state());assertEquals(1,done.items().stream().filter(i->i.state().equals("FAILED")).count());assertFalse(archives.get(reader,tenant,inventory.id()).selectedScopeComplete());assertThrows(IdentityException.class,()->archives.next(reader,tenant,inventory.id(),UUID.randomUUID()));}

 final class Client{final HttpClient http=HttpClient.newBuilder().cookieHandler(new CookieManager(null,CookiePolicy.ACCEPT_ALL)).build();HttpResponse<byte[]> send(String method,String path,Object body,boolean csrf)throws Exception{var r=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+path)).header("Content-Type","application/json");if(csrf){var c=json.readTree(send("GET","/api/v1/auth/csrf",null,false).body());r.header(c.get("headerName").asString(),c.get("token").asString());}return http.send(r.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body))).build(),HttpResponse.BodyHandlers.ofByteArray());}}
 @Test void realHttpConflictAndNoStoreAndSqlPagingGate()throws Exception{var c=new Client();assertEquals(200,c.send("POST","/api/v1/auth/login",Map.of("email",email(admin),"password",password),true).statusCode());var record=offboard();String path="/api/v1/tenants/"+tenant+"/departures/"+record.execution().id();var read=c.send("GET",path,null,false);assertEquals(200,read.statusCode());assertTrue(read.headers().firstValue("cache-control").orElse("").contains("no-store"));var stale=c.send("POST",path,Map.of("requestId",UUID.randomUUID(),"expectedRevision",99,"action","RETRY"),true);assertEquals(409,stale.statusCode());assertEquals("1.0",json.readTree(stale.body()).get("contractVersion").asString());assertEquals("DEPARTURE_REVISION_CONFLICT",json.readTree(stale.body()).get("code").asString());assertFalse(db.queryForObject("SELECT departure_content_readable(?,?,?)",Boolean.class,member,tenant,shared));assertTrue(db.queryForObject("SELECT departure_content_readable(?,?,?)",Boolean.class,reader,tenant,shared));}
 @Test void experienceScrubTriggerErasesAllAffectedTemporaryArchives(){grant(member,"EXPERIENCE_MAINTAIN",shared);var body=new com.dreamcore.workspace.experience.ExperienceService.Content("METHOD","将被清理的独立方法","摘要","实际独立正文",List.of("测试"),"适用","不适用","无","人工整理","INDEPENDENT_COPY");var x=experiences.create(member,tenant,shared,UUID.randomUUID(),body,List.of());experiences.publish(member,tenant,shared,x.id(),UUID.randomUUID(),x.revision(),x.version().id(),true);var e=exit();var inv=archives.create(reader,tenant,e.execution().id(),shared,UUID.randomUUID(),false);var p=archives.next(reader,tenant,inv.id(),UUID.randomUUID());generateArchives();assertTrue(archives.part(reader,tenant,p.id()).canDownload());db.update("UPDATE experience_versions SET scrubbed=true WHERE id=?",x.version().id());assertEquals("REVOKED",archives.receipt(reader,tenant,p.id()).state());assertEquals("COMPLETE",archives.receipt(reader,tenant,p.id()).cleanupState());assertEquals(0,db.queryForObject("SELECT count(*) FROM departure_archive_chunks WHERE part_id=?",Integer.class,p.id()));assertEquals(0,db.queryForObject("SELECT count(*) FROM departure_export_items WHERE part_id=? AND filename IS NOT NULL",Integer.class,p.id()));}
 @Test void inventoryPaginationSplitsActualItemsAndGenerationFencesLateWorker(){for(int i=0;i<51;i++)upload(shared,"版本"+i+".txt");var e=exit();var inv=archives.create(reader,tenant,e.execution().id(),shared,UUID.randomUUID(),false);assertEquals(51,inv.itemCount());var a=archives.next(reader,tenant,inv.id(),UUID.randomUUID());assertEquals(50,a.requestedCount());var b=archives.next(reader,tenant,inv.id(),UUID.randomUUID());assertEquals(1,b.requestedCount());assertEquals(2,archives.parts(reader,tenant,inv.id(),0,20).items().size());var job=archives.claim();var running=archives.part(reader,tenant,job.partId());archives.command(reader,tenant,running.id(),UUID.randomUUID(),running.revision(),"REMOVE");archiveWorker.build(job);assertEquals("REMOVED",archives.receipt(reader,tenant,running.id()).state());assertEquals(0,db.queryForObject("SELECT count(*) FROM departure_archive_chunks WHERE part_id=?",Integer.class,running.id()));}

 @Test void interruptedMaterialRestoreIsReisolatedWhenOriginalDeadlineArrives(){UUID a=upload(personal,"恢复中一.txt"),b=upload(personal,"恢复中二.txt");var e=offboard();processor.process(e.execution().id());var current=service.get(admin,tenant,e.execution().id());service.command(admin,tenant,e.execution().id(),UUID.randomUUID(),current.execution().revision(),"CANCEL_OFFBOARD");assertFalse(bridge.restore(e.execution().id(),1).complete());assertEquals(1,db.queryForObject("SELECT count(*) FROM active_materials WHERE id IN (?,?)",Integer.class,a,b));start=e.execution().deadline().plusSeconds(1);processor.process(e.execution().id());assertEquals(0,db.queryForObject("SELECT count(*) FROM active_materials WHERE id IN (?,?)",Integer.class,a,b));for(int k=0;k<10;k++){drain();processor.process(e.execution().id());}assertEquals("COMPLETE",service.get(admin,tenant,e.execution().id()).execution().state());assertEquals("DISABLED",db.queryForObject("SELECT status FROM tenant_memberships WHERE tenant_id=? AND account_id=?",String.class,tenant,member));assertEquals(2,db.queryForObject("SELECT count(*) FROM departure_materials WHERE execution_id=? AND state='PURGED'",Integer.class,e.execution().id()));}

 @Test void statusProjectionShowsBusinessExitWithoutGivingPlatformContentOrExport(){db.update("INSERT INTO platform_roles(account_id,role) VALUES (?,'PLATFORM_ADMIN')",successor);assertTrue(statuses.get(reader,tenant,false).businessEnabled());var e=exit();assertFalse(statuses.get(reader,tenant,false).businessEnabled());assertTrue(statuses.get(reader,tenant,false).canExport());var platform=statuses.get(successor,tenant,true);assertFalse(platform.businessEnabled());assertFalse(platform.canExport());assertEquals("EXPORT_WINDOW",platform.exitState());assertEquals(e.execution().deadline(),platform.exportDeadline());assertEquals(Set.of("tenantId","businessEnabled","exitState","exportDeadline","canExport"),json.convertValue(platform,Map.class).keySet());db.update("DELETE FROM governance_capabilities WHERE tenant_id=? AND account_id=? AND capability='BULK_EXPORT'",tenant,reader);assertFalse(statuses.get(reader,tenant,false).canExport());}

